  "criteria": {
    "c01_overall_legal_correctness": {"label": "met", "reason": "Svaret gengiver korrekt, at Udbetaling Danmark kan anmode om lægeattest fra den praktiserende læge, når funktionsniveauet ikke kan vurderes. Det angiver også korrekt indholdet: funktionsevne i forhold til den ansøgte funktionsnedsættelse og behov for fortsat behandling eller henvisning til specialist. Ingen af rubrikkens væsentlige fejl forekommer."},
    "c02_required_elements_complete": {"label": "met", "reason": "Alle tre kritiske elementer er med: muligheden for at indhente lægeattest fra praktiserende læge, funktionsevnen i relation til den ansøgte funktionsnedsættelse og behovet for fortsat behandling eller henvisning til yderligere udredning eller behandling hos en specialist."},
    "c03_direct_relevance": {"label": "met", "reason": "Svaret besvarer begge dele af spørgsmålet: hvad Udbetaling Danmark kan gøre, og hvad attesten skal beskrive."},
    "c04_source_traceability": {"label": "not_met", "reason": "Svaret angiver ingen identificerbar kilde (ingen henvisning til vejledningens afsnit eller en lovbestemmelse). Indholdet svarer til afsnit 5.1.2, men det fremgår ikke af selve svaret."},
    "c05_source_validity": {"label": "not_assessable", "reason": "Svaret citerer ingen kilde, så kildens gyldighed kan ikke vurderes."},
    "c06_claim_source_support": {"label": "not_assessable", "reason": "Ingen angivet kilde, så det kan ikke vurderes, om en kilde understøtter påstandene."},
    "c07_no_unsupported_legal_additions": {"label": "met", "reason": "Svaret indeholder ingen regler, betingelser eller retsvirkninger ud over det, der står i afsnit 5.1.2. Det er kun en udeladelse, ikke en tilføjelse."},
    "c08_qualifications_and_exceptions": {"label": "met", "reason": "Svaret bruger 'kan' og fremstiller attesten som en mulighed, ikke en automatisk pligt, og knytter den til situationen, hvor dokumentationen ikke er nok. Fremmødeforbehold kræves kun, hvis fremmøde omtales, og det gør svaret ikke."},
    "c09_reasoning_coherence": {"label": "met", "reason": "Svaret er kort og internt sammenhængende: det angiver betingelsen for at indhente attesten og derefter attestens indhold, uden modsigelser."},
    "c10_legal_modality_precision": {"label": "met", "reason": "'Kan anmode' for Udbetaling Danmarks mulighed og 'skal beskrive' for attestens indhold svarer til kilden ('kan indhente'; 'skal forholde sig til' og 'skal redegøre')."}
  },
  "xhaile_coverage": {
    "A61": {"label": "yes", "reason": "Svaret dækker kernen: lægeattest kan indhentes, når funktionsniveauet ikke kan vurderes, og attesten skal omfatte funktionsevne i forhold til den ansøgte funktionsnedsættelse samt behov for fortsat behandling eller henvisning til specialist. Fremmøde, journaloplysninger og udgifter er supplerende og ikke nævnt, men spørgsmålet kræver dem ikke."}
  },
  "overall_notes": "Indholdsmæssigt korrekt og fuldstændigt i forhold til rubrikken, men svaret nævner ingen kilde. Derfor er C04 not_met, mens C05 og C06 er not_assessable efter kilderegelen."
}

